<?php echo form_open(get_uri('engenharia/checklists/item_save'),array('id'=>'engenharia-item-form','class'=>'general-form')); ?><div class="modal-body"><input type="hidden" name="id" value="<?php echo (int)$model_info->id; ?>"><input type="hidden" name="checklist_id" value="<?php echo (int)$model_info->checklist_id; ?>"><div class="form-group"><label><?php echo app_lang('engenharia_group'); ?></label><select name="group_id" class="form-select"><option value="">-</option><?php foreach($groups as $group){ ?><option value="<?php echo $group->id; ?>" <?php echo (string)$model_info->group_id===(string)$group->id?'selected':''; ?>><?php echo esc($group->title); ?></option><?php } ?></select></div><div class="form-group"><label>* <?php echo app_lang('code'); ?></label><input name="code" class="form-control" value="<?php echo esc($model_info->code); ?>" data-rule-required="true"></div><div class="form-group"><label>* <?php echo app_lang('title'); ?></label><input name="title" class="form-control" value="<?php echo esc($model_info->title); ?>" data-rule-required="true"></div><div class="form-group"><label>* <?php echo app_lang('engenharia_verification'); ?></label><textarea name="question" class="form-control" data-rule-required="true"><?php echo esc($model_info->question); ?></textarea></div><div class="form-group"><label><?php echo app_lang('engenharia_inspector_instruction'); ?></label><textarea name="inspector_instruction" class="form-control"><?php echo esc($model_info->inspector_instruction); ?></textarea></div><div class="form-group"><label><?php echo app_lang('engenharia_norm_reference'); ?></label><input name="norm_reference" class="form-control" value="<?php echo esc($model_info->norm_reference); ?>"></div><div class="row"><div class="form-group col-md-6"><label><?php echo app_lang('engenharia_response_type'); ?></label><select name="response_type" class="form-select"><?php foreach(array('conformity'=>'Conforme / Não conforme / N/A','yes_no'=>'Sim / Não / N/A','tex